import { Table, StringColumn, IntegerColumn, GuidColumn } from '../../db'

/**
 * Relative Duration table - defines relative time calculations like "End of Business Day"
 */
export const cmn_relative_duration = Table({
    extends: 'sys_metadata',
    name: 'cmn_relative_duration',
    label: 'Relative Duration',
    schema: {
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        duration_amount: IntegerColumn({
            label: 'Duration amount',
        }),
        duration_unit: StringColumn({
            label: 'Duration unit',
            maxLength: 40,
            choices: {
                days: {
                    label: 'Days',
                },
                hours: {
                    label: 'Hours',
                },
                minutes: {
                    label: 'Minutes',
                },
            },
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
    },
})
